// Write LM: see write_lm.h. Tables in write_lm_data.h (generated by lm.py).
#include "write_lm.h"
#include "write_lm_data.h"
#include <string.h>

namespace wlm {

using namespace wlm_d;

static inline float deq(uint8_t q) { return -(float)q / 8.0f; }
static inline bool isLetter(char c) { return c >= 'A' && c <= 'Z'; }
static inline bool isDigit(char c) { return c >= '0' && c <= '9'; }
static inline int clsOf(char c) { return isLetter(c) ? c - 'A' : (isDigit(c) ? 26 + c - '0' : -1); }

int decode(const float *logp, const char *word, int len) {
  bool lettersOnly = true, digitsOnly = len > 0;
  for (int i = 0; i < len; i++) {
    if (!isLetter(word[i])) lettersOnly = false;
    if (!isDigit(word[i])) digitsOnly = false;
  }
  int p1 = len >= 1 && isLetter(word[len - 1]) ? word[len - 1] - 'A' : 26;
  int p0 = len >= 2 && isLetter(word[len - 2]) ? word[len - 2] - 'A' : 26;
  const uint8_t *tri = kTri + (p0 * 27 + p1) * 26;
  int best = 0;
  float bestS = -1e30f;
  for (int c = 0; c < kClasses; c++) {
    float s = logp[c];
    if (lettersOnly) s += c < 26 ? kLam * deq(tri[c]) : (len == 0 ? kDigitStart : kDigitLogp);
    else if (digitsOnly && c < 26) s += kDigitLogp;
    if (s > bestS) { bestS = s; best = c; }
  }
  return best;
}

bool correct(const char *typed, int L, const float (*logp)[kClasses], char *out) {
  memcpy(out, typed, L);
  if (L < 2 || L > kMaxLen) return false;
  // Letters with a stray digit ("1APPY") are still words; all digits is a number.
  bool anyLetter = false, allLetters = true;
  for (int i = 0; i < L; i++) {
    if (isLetter(typed[i])) anyLetter = true;
    else if (isDigit(typed[i])) allLetters = false;
    else return false;
  }
  if (kCount[L] == 0) return false;
  bool allDigits = !anyLetter;                     // needs overwhelming evidence (y/o/u read as 7/0/1)
  float typedSc = 0;
  for (int i = 0; i < L; i++) typedSc += logp[i][clsOf(typed[i])];
  float typedF = -255.0f / 8.0f;           // the typed string's own frequency, if listed
  const uint8_t *w = kWords + kOff[L];
  const uint8_t *bestW = nullptr;
  float bestSc = -1e30f;
  for (int k = 0; k < kCount[L]; k++, w += L + 1) {
    float sc = 0;
    bool same = true;
    for (int i = 0; i < L; i++) {
      char up = (char)(w[i] - 'a' + 'A');
      sc += logp[i][up - 'A'];
      if (up != typed[i]) same = false;
    }
    float f = deq(w[L]);
    if (same && typedF < -31.0f) typedF = f;   // first (most frequent) entry
    sc += kAlpha * f;
    if (sc > bestSc) { bestSc = sc; bestW = w; }
  }
  if (!bestW) return false;
  bool sameAsTyped = true;
  for (int i = 0; i < L; i++) if ((char)(bestW[i] - 'a' + 'A') != typed[i]) sameAsTyped = false;
  // A stray digit: take the best word with no margin (the typed string isn't a word).
  float margin = allDigits ? kMargin + (L <= 2 ? kDigitWordMargin : kDigitWordMargin3)
                           : allLetters ? kMargin : 0.0f;
  if (sameAsTyped || bestSc <= typedSc + kAlpha * typedF + margin) return false;
  for (int i = 0; i < L; i++) out[i] = (char)(bestW[i] - 'a' + 'A');
  return true;
}

}  // namespace wlm

namespace wlm {

int wordStatus(const char *w, int L, float *logf) {
  int st = 0;
  if (logf) *logf = -1e9f;
  if (L < 1) return kPrefix;
  for (int i = 0; i < L; i++) if (!isLetter(w[i])) return 0;
  for (int len = L; len <= kMaxLen; len++) {
    const uint8_t *p = kWords + kOff[len];
    for (int k = 0; k < kCount[len]; k++, p += len + 1) {
      bool same = true;
      for (int i = 0; i < L && same; i++) same = (char)(p[i] - 'a' + 'A') == w[i];
      if (!same) continue;
      if (len == L) {
        if (!(st & kWord) && logf) *logf = deq(p[L]);      // first entry = most frequent
        st |= kWord;
      } else {
        st |= kPrefix;
      }
      if (st == (kWord | kPrefix) && (!logf || *logf > -1e8f)) return st;
    }
  }
  return st;
}

}  // namespace wlm
